function removeAnagrams(words) {
  const result = [];
  let previousKey = '';

  for (const word of words) {
    const counts = new Array(26).fill(0);
    for (const ch of word) {
      counts[ch.charCodeAt(0) - 97]++;
    }
    const key = counts.join(',');
    if (key !== previousKey) {
      result.push(word);
    }
    previousKey = key;
  }
  return result;
}

