function removeAnagrams(words) {
  const list = words.slice();
  const sorted = w => w.split('').sort().join('');
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = list.length - 1; i > 0; i--) {
      if (sorted(list[i]) === sorted(list[i - 1])) {
        list.splice(i, 1);
        changed = true;
        break;
      }
    }
  }
  return list;
}

