function generate(rand, size) {
  const letters = size === 'large' ? 'abcde' : 'abc';
  const maxLength = size === 'large' ? 10 : 3;
  const fresh = () => {
    const length = 1 + Math.floor(rand() * maxLength);
    let text = '';
    for (let i = 0; i < length; i++) text += letters[Math.floor(rand() * letters.length)];
    return text;
  };
  const shuffle = word => {
    const chars = word.split('');
    for (let i = chars.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [chars[i], chars[j]] = [chars[j], chars[i]];
    }
    return chars.join('');
  };
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const words = [];
  for (let i = 0; i < n; i++) {
    // Often reuse the previous word's letters so that runs of anagrams appear.
    if (i > 0 && rand() < 0.5) words.push(shuffle(words[i - 1]));
    else words.push(fresh());
  }
  return [words];
}
